import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-114: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short114', durationInSeconds: 32.8, fps: 30, width: 1080, height: 1920 };

const B0 = secToFrame(2.4);
const B1 = secToFrame(8.3);
const B2 = secToFrame(10.1);
const B3 = secToFrame(14.1);
const B4 = secToFrame(16.1);
const B5 = secToFrame(20.7);
const B6 = secToFrame(22.9);
const B7 = secToFrame(27.0);
const CTA = secToFrame(30.4);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short114: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B0}>
        <CoverImage src="projects/short-114/cover.png" out={B0 - 10} />
        <HookTitle hold onDark kicker="AI PRICE CHANGES" lines={[{ text: "CLAUDE NO HIKE" },{ text: "GEMINI DOUBLES", accent: true }]} />
      </FadeOut>
      <FadeOut at={B1}>
        <ToolCard name="Claude Sonnet 5" tagline="Planned Sept 1 hike." chip="$3 / $15" at={B0 - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="planned in" v="$3.00" bad />
            <Line k="planned out" v="$15.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="Never happened" tagline="Hike cancelled." chip="CANCELLED" at={B1 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Sept 1 increase" v="will not occur" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="Sonnet 5 today" tagline="Standard price." chip="$2 / $10" at={B2 - 2}>
          <Panel>
            <Line k="input /1M" v="$2.00" good />
            <Line k="output /1M" v="$10.00" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="Google goes up" tagline="Opposite direction." chip="DEC 1" at={B3 - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="Gemini 4 Argon" v="Dec 1" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B5}>
        <ToolCard name="Gemini 4 Argon" tagline="Input doubles." chip="$2 to $4" at={B4 - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="input now" v="$2.00" />
            <Line k="from Dec 1" v="$4.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B6}>
        <ToolCard name="Argon output" tagline="Doubles too." chip="$10 to $20" at={B5 - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="output now" v="$10.00" />
            <Line k="from Dec 1" v="$20.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B7}>
        <ToolCard name="Gemini 3.8 Flash" tagline="Doubles Jan 1." chip="JAN 1" at={B6 - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="input" v="$0.75 to $1.50" bad />
            <Line k="output" v="$3.75 to $7.50" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Same model" tagline="Double the bill." chip="2X" at={B7 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Claude Sonnet 5" v="$2 / $10" good />
            <Line k="Argon from Dec 1" v="$4 / $20" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-114/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="AI PRICE CHANGES" lines={[{ text: "CLAUDE NO HIKE" },{ text: "GEMINI DOUBLES", accent: true }]} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Cancelled versus doubled.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short114;
